public sealed partial class Cs2TsPlugin
{
    /// <summary>
    /// Hooks one game event with the server, the first time a script asks for it.
    ///
    /// Nothing is hooked in advance. A script that listens for three events pays for
    /// three, and the rest of the game's events never reach this plugin at all.
    ///
    /// One method per event rather than one body with every registration in it, and
    /// that is not tidiness. The single-method version was measured on a server at
    /// 800 ms for the first hook and under 2 ms for every one after it: the whole
    /// method has to be compiled before any of it runs, and two hundred and seventy
    /// three generic registrations is a lot to compile. 800 ms is past the watchdog's
    /// budget, so the script that asked was killed mid-load. Split up, only the one
    /// method that is called gets compiled.
    /// </summary>
    /// <returns>Whether the name is a game event at all.</returns>
    private bool HookGameEvent(string name)
    {
        switch (name)
        {
            case "achievement_earned": HookAchievementEarnedEvent(); return true;
            case "achievement_earned_local": HookAchievementEarnedLocalEvent(); return true;
            case "achievement_event": HookAchievementEventEvent(); return true;
            case "achievement_info_loaded": HookAchievementInfoLoadedEvent(); return true;
            case "achievement_write_failed": HookAchievementWriteFailedEvent(); return true;
            case "add_bullet_hit_marker": HookAddBulletHitMarkerEvent(); return true;
            case "add_player_sonar_icon": HookAddPlayerSonarIconEvent(); return true;
            case "ammo_pickup": HookAmmoPickupEvent(); return true;
            case "ammo_refill": HookAmmoRefillEvent(); return true;
            case "announce_phase_end": HookAnnouncePhaseEndEvent(); return true;
            case "begin_new_match": HookBeginNewMatchEvent(); return true;
            case "bomb_abortdefuse": HookBombAbortdefuseEvent(); return true;
            case "bomb_abortplant": HookBombAbortplantEvent(); return true;
            case "bomb_beep": HookBombBeepEvent(); return true;
            case "bomb_begindefuse": HookBombBegindefuseEvent(); return true;
            case "bomb_beginplant": HookBombBeginplantEvent(); return true;
            case "bomb_defused": HookBombDefusedEvent(); return true;
            case "bomb_dropped": HookBombDroppedEvent(); return true;
            case "bomb_exploded": HookBombExplodedEvent(); return true;
            case "bomb_pickup": HookBombPickupEvent(); return true;
            case "bomb_planted": HookBombPlantedEvent(); return true;
            case "bonus_updated": HookBonusUpdatedEvent(); return true;
            case "bot_takeover": HookBotTakeoverEvent(); return true;
